"use client"

import * as React from "react"

import { Cancel01Icon } from "@hugeicons/core-free-icons"
import { HugeiconsIcon } from "@hugeicons/react"

import { cn } from "@/lib/utils"
import { Icon, type IconName } from "@/components/ui/icon"

import { useAmbientRuntime } from "./ambient-runtime"
import { useAssistant, type ContextChip } from "./assistant-context"
import { OrbCharacter } from "./orb-character"

/**
 * THE SHARED MARKS — the small pieces the assistant's own input row wears.
 *
 * These lived in assistant.tsx, which is the 1,700-line surface shell. Only
 * composer.tsx used them, and that one import edge meant EVERY component in
 * the layer transitively required the entire surface: asking the registry for
 * a ReasoningPanel produced sixteen files, nearly the whole package.
 *
 * Nothing here is new. They were always a separate thing — the shell just
 * happened to be where they were written. Splitting them costs nothing and
 * lets a kit be installed as a kit.
 */


/**
 * THE AI FORM'S PLACEHOLDER — the shimmer belongs to every ambient input,
 * not just the palette's: it is how a form says the assistant is listening.
 * Rendered as an overlay because an <input>'s own placeholder can't carry a
 * background-clipped gradient.
 */
export function ShimmerPlaceholder({
  show,
  children,
  className,
}: {
  show: boolean
  children: React.ReactNode
  className?: string
}) {
  if (!show) return null
  return (
    <span
      aria-hidden
      className={cn(
        // inset-0, not left-0: the ghost stands in for a single-line <input>,
        // so it must be bounded by the field's box and truncate the way the
        // input would. Unbounded, a long suggestion wrapped to two lines the
        // moment the scaling base grew (95% fit by luck; 100% did not).
        "ambient-shimmer pointer-events-none absolute inset-0 flex items-center text-base",
        className
      )}
    >
      <span className="truncate">{children}</span>
    </span>
  )
}


/**
 * The assistant's mark: the real OrbCharacter — one shader instance per
 * surface mark, riding the live ambient state. (The CSS OrbGlyph remains
 * for incidental marks: the footer brand and settled transcript entries,
 * where a context per row would stack up — DESIGN.md §12.)
 */
export function AssistantMark({ size }: { size: number }) {
  const runtime = useAmbientRuntime()
  const { orbState } = useAssistant()
  return (
    <span className="inline-flex shrink-0">
      <OrbCharacter
        size={size}
        state={orbState}
        colors={runtime.orb.useAccent ? undefined : runtime.orb.colors}
        speeds={runtime.orb.speeds}
      />
    </span>
  )
}


/**
 * What each kind of context LOOKS like. Sparkles is gone from this map on
 * purpose: in this system sparkles means the ASSISTANT — its mark, AskAI,
 * the follow-up heading — and a context chip is not the assistant. It is the
 * thing the assistant can see, so it wears the icon of the thing.
 *
 * Names, not icon modules: these are drawn by whichever library the
 * Foundation has configured (rule 6), like every other icon in the product.
 */
const chipKindIcon: Record<ContextChip["kind"], IconName> = {
  page: "document",
  control: "sliders",
  target: "layers",
  cell: "layers",
  file: "code",
  symbol: "code",
  selection: "type",
}


export function IconTile({
  icon,
  compact,
}: {
  icon: IconName
  compact?: boolean
}) {
  return (
    <span
      className={cn(
        "flex shrink-0 items-center justify-center bg-[var(--ambient-accent-wash)] text-[var(--ambient-accent)]",
        compact ? "size-4 rounded-[4px]" : "size-5 rounded-[5px]"
      )}
    >
      <Icon name={icon} size={compact ? 10 : 12} />
    </span>
  )
}


/**
 * CONTEXT CHIP — one attachment the assistant will answer against: the page
 * itself, or anything the user right-clicked into the conversation.
 *
 * THE ANATOMY IS ONE OBJECT, not a per-surface treatment: icon tile (typed by
 * what was attached) · label · a squared remove control. Two sizes only —
 * `default` where the composer has a row of its own (palette, panel), and
 * `compact` where chips share a line with the input (quick ask). Nothing
 * else varies; a surface picks the size, never the look.
 */
export function ContextChipView({
  chip,
  compact,
  onRemove,
  className,
}: {
  chip: ContextChip
  compact?: boolean
  onRemove?: () => void
  className?: string
}) {
  return (
    <span
      className={cn(
        // shrink-0: these ride in a scrolling slider, where a flex child that
        // shrinks squeezes instead of scrolling and every chip loses its label
        "inline-flex max-w-full shrink-0 items-center rounded-lg border border-border bg-(--wash) font-medium",
        compact
          ? "gap-1.5 py-0.5 ps-1 pe-0.5 text-[11.5px]"
          : "gap-2 py-1 ps-1.5 pe-1 text-[12.5px]",
        className
      )}
    >
      {/* the chip's own icon when it has one — the page knows what it is */}
      <IconTile icon={chip.icon ?? chipKindIcon[chip.kind]} compact={compact} />
      <span className="max-w-56 min-w-0 truncate">{chip.label}</span>
      {onRemove && (
        <button
          type="button"
          aria-label={`Remove ${chip.label}`}
          onClick={onRemove}
          className={cn(
            "flex shrink-0 items-center justify-center rounded-md bg-accent text-muted-foreground hover:text-foreground",
            compact ? "size-[18px]" : "size-[22px]"
          )}
        >
          <HugeiconsIcon
            icon={Cancel01Icon}
            size={compact ? 11 : 13}
            strokeWidth={1.8}
          />
        </button>
      )}
    </span>
  )
}

/* eslint-disable react-refresh/only-export-components --
   Same shape, same reason as foundation-context.tsx: one concept's contract,
   defaults, provider and hooks belong in one module. Splitting them to satisfy
   Fast Refresh would put the interface in one file and its only implementation
   in another, for a dev-ergonomics win on a file that changes rarely. */
"use client"

import * as React from "react"

import { DEFAULT_STATE_SPEEDS, type OrbState } from "./kit-vocabulary"

/**
 * THE AMBIENT LAYER'S RUNTIME — everything it needs from a design system, and
 * nothing else.
 *
 * The layer used to read the Foundation directly. That was correct while both
 * lived in one app and fatal the moment anyone wanted the layer without it:
 * eight files importing `@/foundation/foundation-context` is eight hard
 * dependencies on 792 lines of configurator, to consume seven values.
 *
 * So the dependency is inverted. This file states the contract; the Foundation
 * *implements* it (see the bridge in foundation-context.tsx). The layer now
 * asks for what it needs rather than reaching for where it happens to live.
 *
 * THE CONTEXT HAS A REAL DEFAULT AND THE HOOK NEVER THROWS. That is the whole
 * point, and the deliberate opposite of `useFoundation()`, which throws
 * outside its provider. `<Assistant />` mounted in a bare app must render and
 * animate correctly on these values — if it ever cannot, this file is wrong,
 * not the app.
 *
 * The defaults below are not invented. They mirror two existing sources and
 * must keep mirroring them:
 *   · the motion numbers = the "productive" character in foundation-context.tsx
 *     and the `--motion-*` block in packages/ui globals.css (both 120/180/240/
 *     320ms on cubic-bezier(0.2, 0, 0, 1))
 *   · the orb cadence = DEFAULT_STATE_SPEEDS, imported rather than restated
 * Two copies of one value is this project's named failure mode; where a copy is
 * unavoidable, the comment naming the other copy is the mitigation.
 */

export type MotionRole = "micro" | "control" | "surface" | "page"

export type AmbientEase = [number, number, number, number]

export type AmbientTransition = { duration: number; ease: AmbientEase }

export type AmbientSpring = {
  type: "spring"
  stiffness: number
  damping: number
}

export interface AmbientRuntime {
  /**
   * Where the layer's own static assets are served from — the orb's shader
   * shapes (orb-circle.svg and the rect family), which the registry installs
   * into the host's `public/`.
   *
   * It is a value rather than a hardcoded "/" because a site served from a
   * subpath (GitHub Pages project sites, any app mounted under a prefix)
   * resolves a root-absolute URL against the DOMAIN, not the app — so the
   * shader silently loads nothing and the orb goes cold. Default "/" is
   * correct for an app at the root, which is most of them.
   */
  assetBase: string
  /** How a message is presented — see MessagePair. */
  messageVariant: "bubble" | "flat"
  /** The pace StreamingText types at. */
  streamCharsPerSecond: number
  /** The orb's palette and per-state cadence. */
  orb: {
    useAccent: boolean
    colors: string[]
    speeds: Record<OrbState, number>
  }
  /** The framer-motion tween for a motion role (DESIGN.md §5). */
  motionTransition: (role: MotionRole) => AmbientTransition
  /** The spring for interruptible/gestural motion. */
  motionSpring: () => AmbientSpring
}

/* Mirrors globals.css `:root` and the "productive" motion character. */
const DEFAULT_DURATIONS_MS: Record<MotionRole, number> = {
  micro: 120,
  control: 180,
  surface: 240,
  page: 320,
}
const DEFAULT_EASE: AmbientEase = [0.2, 0, 0, 1]

export const DEFAULT_AMBIENT_RUNTIME: AmbientRuntime = {
  assetBase: "/",
  messageVariant: "bubble",
  streamCharsPerSecond: 60,
  orb: {
    useAccent: true,
    colors: ["#8bd8ff", "#2563eb", "#0b1e55"],
    speeds: DEFAULT_STATE_SPEEDS,
  },
  motionTransition: (role) => ({
    duration: DEFAULT_DURATIONS_MS[role] / 1000,
    ease: DEFAULT_EASE,
  }),
  motionSpring: () => ({ type: "spring", stiffness: 380, damping: 32 }),
}

const AmbientRuntimeContext = React.createContext<AmbientRuntime>(
  DEFAULT_AMBIENT_RUNTIME
)

/**
 * Supplies a runtime. Anything omitted falls back to the default, so a host
 * can override the stream pace without knowing what a motion role is.
 */
export function AmbientRuntimeProvider({
  value,
  children,
}: {
  value?: Partial<AmbientRuntime>
  children: React.ReactNode
}) {
  const runtime = React.useMemo<AmbientRuntime>(
    () => (value ? { ...DEFAULT_AMBIENT_RUNTIME, ...value } : DEFAULT_AMBIENT_RUNTIME),
    [value]
  )
  return (
    <AmbientRuntimeContext.Provider value={runtime}>
      {children}
    </AmbientRuntimeContext.Provider>
  )
}

/** Never throws — see the header. A bare mount is a supported configuration. */
export function useAmbientRuntime() {
  return React.useContext(AmbientRuntimeContext)
}

/** The framer-motion tween for a motion role. */
export function useMotionTransition(role: MotionRole) {
  return useAmbientRuntime().motionTransition(role)
}

/** The configured character's spring. */
export function useMotionSpring() {
  return useAmbientRuntime().motionSpring()
}

/**
 * Resolve one of the layer's own assets against the host's base. Tolerates a
 * base with or without its trailing slash, because both spellings are common
 * and the failure (a doubled or missing slash) is silent.
 */
export function useAmbientAsset(file: string) {
  const base = useAmbientRuntime().assetBase
  return `${base.replace(/\/$/, "")}/${file.replace(/^\//, "")}`
}

/* eslint-disable react-refresh/only-export-components */
"use client"

import * as React from "react"

import type { IconName } from "@/components/ui/icon"

import type { OrbState } from "./orb-character"

export type AssistantMode =
  | "line"
  | "panel"
  | "dock"
  | "spotlight"
  | "history"

export type OrbAnchor = "tl" | "tc" | "tr" | "ml" | "mr" | "bl" | "bc" | "br"

export type ContextChip = {
  id: string
  label: string
  /**
   * What was attached. The kind picks the chip's mark and tells the composer
   * what sort of answer the question deserves — a file earns tool calls and a
   * diff, a page earns a search and citations.
   */
  kind: "page" | "control" | "target" | "cell" | "file" | "symbol" | "selection"
  /**
   * What this particular thing IS, when the kind is too coarse to say. Every
   * page is `kind: "page"`, but a page can be an editor, a colour map or a
   * motion table — and the page is the only thing that knows which. Omitted,
   * the kind's own icon stands in.
   */
  icon?: IconName
}

/**
 * What the page knows that the ambient layer should surface: the questions
 * worth asking RIGHT NOW (live — a healed problem leaves the list) and the
 * working history this surface would plausibly have. Announced by the page
 * like pageChip is; the layer renders it and falls back to its generic
 * defaults when no page has spoken.
 */
export type PageIntel = {
  suggestions?: string[]
  recents?: { text: string; when: string }[]
  /**
   * What "Jump to" navigates to while this page is open. A page with its own
   * workspace — the dev tool's files — offers those instead of the app's
   * routes: the palette should move you around where you are working, not
   * away from it.
   */
  jumps?: { id: string; label: string; desc?: string }[]
  onJump?: (id: string) => void
  /**
   * What the spotlight's input invites here. The generic line asks about the
   * app; a page with its own material can ask about that instead.
   */
  askPlaceholder?: string
  /** Section headings, when the page's own words are more useful. */
  suggestLabel?: string
  jumpLabel?: string
}

/**
 * A COMMAND the palette can run. The app registers these; the layer renders
 * them and calls `run`. It never learns what a command means — same contract
 * as the context chip, in the other direction.
 */
/**
 * A place the host app can navigate to, offered in the palette's "Jump to".
 *
 * THE LAYER IS TOLD, NEVER IMPORTS. assistant.tsx used to `import { sections }
 * from "@/nav"` — a UI layer reaching into one particular app's route table,
 * and the single thing that made it un-liftable. `icon` is deliberately
 * `unknown`: the layer only forwards it to the host's own Icon, so no icon
 * library leaks into the public contract.
 */
export type NavItem = {
  id: string
  label: string
  desc?: string
  icon?: unknown
}

export type AmbientCommand = {
  id: string
  /** The group heading it files under: "Components", "Documentation"… */
  section: string
  label: string
  desc?: string
  /** Extra words to match on that are not worth showing. */
  keywords?: string
  /** An icon NAME from the vocabulary, drawn by the configured library. */
  icon?: string
  run: () => void
}

type AssistantState = {
  mode: AssistantMode
  setMode: (m: AssistantMode) => void
  /** Ambient context — what the user is currently looking at. Replaced on navigation/selection. */
  pageChip: ContextChip | null
  setPageChip: (c: ContextChip | null) => void
  /** What the current page suggests and remembers — see PageIntel. */
  pageIntel: PageIntel | null
  setPageIntel: (i: PageIntel | null) => void
  /** Everything ⌘K can DO, registered by the app — see AmbientCommand. */
  commands: AmbientCommand[]
  setCommands: (c: AmbientCommand[]) => void
  /** Where the host can go — see NavItem. Empty is a valid state. */
  navItems: NavItem[]
  /** Explicit context added by the user (right-click → Explain / Add to context). */
  chips: ContextChip[]
  addChip: (c: ContextChip) => void
  removeChip: (id: string) => void
  /** Right-click → Explain: attach context and open the assistant with a seeded prompt. */
  explain: (c: ContextChip) => void
  seedVersion: number
  consumeSeededPrompt: () => string | null
  /**
   * Hand a prompt to the next surface. autoSend asks it on arrival;
   * immediate skips the thinking beat, for a surface that already showed it.
   */
  seedPrompt: (text: string, autoSend?: boolean, immediate?: boolean) => void
  /** True once, if the pending seed should be sent rather than typed. */
  consumeAutoSend: () => boolean
  /** True once, if the pending seed should compose without the thinking beat. */
  consumeImmediate: () => boolean
  orbAnchor: OrbAnchor
  setOrbAnchor: (a: OrbAnchor) => void
  /** The orb character's state — driven by the response pipeline. */
  orbState: OrbState
  setOrbState: (s: OrbState) => void
  /** Navigate the app shell to a section (wired by App). */
  navigate?: (sectionId: string) => void
  /**
   * The last workspace effect a settled answer announced. Surfaces that own
   * product state subscribe and decide what it means; the layer only relays.
   */
  workspaceEffect: string | null
  announceEffect: (effect: string | null) => void
}

const AssistantContext = React.createContext<AssistantState | undefined>(undefined)

export function AssistantProvider({
  children,
  onNavigate,
  navItems = [],
}: {
  children: React.ReactNode
  onNavigate?: (sectionId: string) => void
  navItems?: NavItem[]
}) {
  const [mode, setMode] = React.useState<AssistantMode>("line")
  const [pageChip, setPageChip] = React.useState<ContextChip | null>(null)
  const [pageIntel, setPageIntel] = React.useState<PageIntel | null>(null)
  const [commands, setCommands] = React.useState<AmbientCommand[]>([])
  const [chips, setChips] = React.useState<ContextChip[]>([])
  const [seedVersion, setSeedVersion] = React.useState(0)
  const [workspaceEffect, announceEffect] = React.useState<string | null>(null)
  const [orbAnchor, setOrbAnchor] = React.useState<OrbAnchor>("bc")
  const [orbState, setOrbState] = React.useState<OrbState>("still")
  const seededRef = React.useRef<string | null>(null)

  const addChip = React.useCallback((c: ContextChip) => {
    setChips((prev) => (prev.some((p) => p.id === c.id) ? prev : [...prev, c]))
  }, [])

  const removeChip = React.useCallback((id: string) => {
    setChips((prev) => prev.filter((c) => c.id !== id))
  }, [])

  const explain = React.useCallback(
    (c: ContextChip) => {
      addChip(c)
      seededRef.current = `Explain ${c.label}`
      setSeedVersion((v) => v + 1)
      setMode("panel")
    },
    [addChip]
  )

  const consumeSeededPrompt = React.useCallback(() => {
    const p = seededRef.current
    seededRef.current = null
    return p
  }, [])

  const autoSendRef = React.useRef(false)
  const immediateRef = React.useRef(false)
  const seedPrompt = React.useCallback(
    (text: string, autoSend = false, immediate = false) => {
      seededRef.current = text
      autoSendRef.current = autoSend
      immediateRef.current = immediate
      setSeedVersion((v) => v + 1)
    },
    []
  )
  const consumeAutoSend = React.useCallback(() => {
    const a = autoSendRef.current
    autoSendRef.current = false
    return a
  }, [])
  const consumeImmediate = React.useCallback(() => {
    const i = immediateRef.current
    immediateRef.current = false
    return i
  }, [])

  const value = React.useMemo(
    () => ({
      mode,
      setMode,
      pageChip,
      setPageChip,
      pageIntel,
      setPageIntel,
      commands,
      setCommands,
      chips,
      addChip,
      removeChip,
      explain,
      seedVersion,
      seedPrompt,
      consumeAutoSend,
      consumeImmediate,
      consumeSeededPrompt,
      orbAnchor,
      setOrbAnchor,
      orbState,
      setOrbState,
      navigate: onNavigate,
      navItems,
      workspaceEffect,
      announceEffect,
    }),
    [mode, pageChip, pageIntel, commands, chips, addChip, removeChip, explain, seedVersion, seedPrompt, consumeAutoSend, consumeImmediate, consumeSeededPrompt, orbAnchor, orbState, onNavigate, navItems, workspaceEffect]
  )

  return (
    <AssistantContext.Provider value={value}>
      {children}
    </AssistantContext.Provider>
  )
}

export function useAssistant() {
  const ctx = React.useContext(AssistantContext)
  if (!ctx) throw new Error("useAssistant must be used within AssistantProvider")
  return ctx
}

"use client"

import * as React from "react"
import {
  DEFAULT_STATE_SPEEDS,
  type OrbState,
} from "./kit-vocabulary"

import { Heatmap } from "@paper-design/shaders-react"
import { animate, useAnimationFrame, useMotionValue } from "framer-motion"

import { cn } from "@/lib/utils"

import { useAmbientAsset, useAmbientRuntime } from "./ambient-runtime"

/**
 * The orb character — the assistant's animated identity: the Paper Design
 * heatmap shader wrapped around a circle, so heat flows around the orb's
 * edge like thermal energy. (The one sanctioned shader surface, DESIGN.md
 * §5 — implemented via @paper-design/shaders-react.)
 *
 * Each state has its own MOVEMENT, not just speed — the heat itself
 * behaves differently:
 * - "still"     — calm, balanced glow breathing around the edge.
 * - "listening" — heat drawn INWARD (inner glow dominates, waves angled
 *                 in): the orb absorbing what it hears.
 * - "thinking"  — hot: fast flow, high contour, grain, heat radiating
 *                 both ways — the orb working.
 * - "answer"    — a one-shot outward bloom (outer glow surges and decays),
 *                 then a slow, settled glow: found it.
 *
 * Transitions are continuous — every parameter is a Framer Motion spring
 * (the sanctioned animation library, DESIGN.md §5) retargeted on state
 * change, so velocity carries through: a state change is a transition,
 * never a cut, and interrupting one mid-flight stays smooth. Per-state
 * speeds and the palette come from the Foundation orb config; palette is
 * accent-linked by default (a thermal ramp derived from the accent) or
 * custom colors used as the heat ramp (cold → hot).
 */




/** Per-state movement targets for the heat itself. */
const STATE_PARAMS: Record<
  OrbState,
  {
    speed: number
    contour: number
    innerGlow: number
    outerGlow: number
    noise: number
    angle: number
  }
> = {
  still: { speed: 0.5, contour: 0.5, innerGlow: 0.35, outerGlow: 0.3, noise: 0, angle: 0 },
  listening: { speed: 0.7, contour: 0.62, innerGlow: 0.8, outerGlow: 0.1, noise: 0, angle: 180 },
  thinking: { speed: 2.2, contour: 0.92, innerGlow: 0.5, outerGlow: 0.55, noise: 0, angle: 90 },
  answer: { speed: 0.45, contour: 0.68, innerGlow: 0.45, outerGlow: 0.42, noise: 0, angle: 0 },
}

/**
 * Where every heat surface WAKES from: hotter than any resting state, so
 * the first seconds after mount are visibly alive — the springs then
 * settle into the actual state. Without this, a page that loads into
 * `still` reads as a frozen image until the first state change.
 */
const WAKE_PARAMS = {
  speed: 2.4,
  contour: 0.9,
  innerGlow: 0.6,
  outerGlow: 0.6,
  noise: 0,
  angle: 120,
}

/** The shape the heat wraps: a filled circle with room for the outer
    glow. Served as a real file — the shader's loader rejects data URIs.
    The NAME only: the host's assetBase resolves it (useAmbientAsset), so a
    site under a subpath does not silently load nothing. */
const CIRCLE_IMAGE = "orb-circle.svg?v=2"

/**
 * Resolve any CSS color string to hex — including oklch(), which is what
 * Tailwind v4's palette variables actually contain. Canvas fillStyle
 * echoes oklch back verbatim, so rasterize a pixel and read it: the only
 * conversion that works for every color syntax the tokens might use.
 */
function resolveHex(css: string): string {
  const value = css.trim() || "#2563eb"
  if (/^#[0-9a-f]{6}$/i.test(value)) return value
  const canvas = document.createElement("canvas")
  canvas.width = canvas.height = 1
  const ctx = canvas.getContext("2d", { willReadFrequently: true })
  if (!ctx) return "#2563eb"
  ctx.fillStyle = value
  ctx.fillRect(0, 0, 1, 1)
  const [r, g, b] = ctx.getImageData(0, 0, 1, 1).data
  return rgbToHex(r!, g!, b!)
}

function hexToRgb(hex: string): [number, number, number] {
  const n = parseInt(hex.slice(1, 7), 16)
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255]
}
function rgbToHex(r: number, g: number, b: number): string {
  const c = (v: number) =>
    Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, "0")
  return "#" + c(r) + c(g) + c(b)
}

/** Accent-linked thermal ramp: cold deep accent -> accent -> pale -> hot complement. */
function accentRamp(): string[] {
  const css = getComputedStyle(document.documentElement).getPropertyValue(
    "--ambient-accent"
  )
  const [r, g, b] = hexToRgb(resolveHex(css))
  return [
    // cold end transparent — the heat lives at the rim; the core is a
    // separate CSS layer under the canvas
    rgbToHex(r * 0.45, g * 0.45, b * 0.6) + "00",
    rgbToHex(r * 0.45, g * 0.45, b * 0.6) + "55",
    rgbToHex(r, g, b),
    rgbToHex(r * 0.35 + 166, g * 0.35 + 166, b * 0.35 + 166),
    rgbToHex(b, r, g),
    rgbToHex(255, Math.max(g, 120), 60),
  ]
}

/**
 * The orb at glyph scale — a pure-CSS stand-in for marks and avatars
 * (≤32px), where the shader's detail is invisible but its cost is not:
 * every OrbCharacter is a fresh WebGL context, a shader compile, and a
 * 60fps loop, which is exactly what made surfaces stutter on open. Same
 * anatomy (glass shell, accent core), zero runtime cost.
 */
export function OrbGlyph({
  size = 20,
  color,
  state,
  className,
}: {
  size?: number
  /** Core color; defaults to the ambient accent. */
  color?: string
  /** Ambient state — paces the glyph's breath (CSS, no shader). */
  state?: OrbState
  className?: string
}) {
  const core = color ?? "var(--ambient-accent)"
  return (
    <span
      aria-hidden
      data-orb-state={state ?? "still"}
      className={cn("relative inline-block shrink-0 rounded-full", className)}
      style={{
        width: size,
        height: size,
        backgroundColor: "var(--glass-core)",
        boxShadow: "inset 0 0 0 1px var(--glass-border)",
      }}
    >
      <span
        className="ambient-glyph-orbit absolute rounded-full"
        style={{ inset: "12%" }}
      />
      <span
        className="ambient-glyph-core absolute rounded-full"
        style={{
          inset: "20%",
          background: `radial-gradient(circle at 35% 30%, color-mix(in oklab, ${core} 55%, white), ${core} 58%, color-mix(in oklab, ${core} 62%, black))`,
          filter: "blur(0.5px)",
        }}
      />
    </span>
  )
}

/**
 * A LOST WebGL CONTEXT FREEZES A HEAT SURFACE ON ITS LAST FRAME — the
 * browser caps live contexts per page and evicts the oldest when a new
 * one is created, which is exactly the long-lived surfaces (the wordmark,
 * the page ground). The canvas announces the loss; remounting the shader
 * builds a fresh context, so the identity never quietly dies. Every heat
 * surface wears this listener.
 */
function useShaderEpoch(
  hostRef: React.RefObject<HTMLElement | null>,
  ready: boolean
) {
  const [epoch, setEpoch] = React.useState(0)
  React.useEffect(() => {
    if (!ready) return
    const canvas = hostRef.current?.querySelector("canvas")
    if (!canvas) return
    const onLost = (e: Event) => {
      e.preventDefault()
      setEpoch((n) => n + 1)
    }
    canvas.addEventListener("webglcontextlost", onLost)
    return () => canvas.removeEventListener("webglcontextlost", onLost)
  }, [hostRef, ready, epoch])
  return epoch
}

export interface OrbCharacterProps {
  state?: OrbState
  /** Diameter in px. */
  size?: number
  /** Global motion multiplier — 1 is the designed cadence. */
  speed?: number
  /** Custom heat ramp (cold -> hot, 1-4 CSS colors). Omit for accent-linked. */
  colors?: string[]
  /** Per-state cadence multipliers; merged over DEFAULT_STATE_SPEEDS. */
  speeds?: Partial<Record<OrbState, number>>
  className?: string
}

/**
 * The shared heat engine: spring-driven shader params + the palette, one
 * state machine for every heat surface (the orb character, the ambient
 * field). Springs carry velocity across retargets; the answer state runs
 * its one-shot outward bloom.
 */
function useHeatEngine({
  state,
  speed = 1,
  speeds,
  colors,
}: {
  state: OrbState
  speed?: number
  speeds?: Partial<Record<OrbState, number>>
  colors?: string[]
}) {
  const [params, setParams] = React.useState(() => ({ ...WAKE_PARAMS }))
  const [palette, setPalette] = React.useState<string[]>([])

  // Each shader parameter is a spring-driven motion value. Springs carry
  // velocity across retargets, so a state change mid-transition leans in
  // and settles out instead of restarting — the S-curve the character
  // needs, for free. Per-parameter spring characters: the flow speed
  // glides, the glows breathe, the wave direction swings deliberately.
  const mv = {
    speed: useMotionValue(WAKE_PARAMS.speed),
    contour: useMotionValue(WAKE_PARAMS.contour),
    innerGlow: useMotionValue(WAKE_PARAMS.innerGlow),
    outerGlow: useMotionValue(WAKE_PARAMS.outerGlow),
    angle: useMotionValue(WAKE_PARAMS.angle),
  }
  const mvRef = React.useRef(mv)
  // the frame loop reads the latest values, so the ref is refreshed after
  // commit rather than during render (React may render without committing)
  React.useEffect(() => {
    mvRef.current = mv
  })

  // per-state cadence config scales the heat's flow speed
  const speedFactor =
    ((speeds?.[state] ?? DEFAULT_STATE_SPEEDS[state]) /
      DEFAULT_STATE_SPEEDS[state]) *
    (speed ?? 1)

  React.useEffect(() => {
    const m = mvRef.current
    const target = STATE_PARAMS[state]
    const spring = (opts: { stiffness: number; damping: number; mass?: number }) =>
      ({ type: "spring", ...opts }) as const

    const controls = [
      animate(m.speed, target.speed * speedFactor, spring({ stiffness: 50, damping: 18, mass: 1.2 })),
      animate(m.innerGlow, target.innerGlow, spring({ stiffness: 110, damping: 20 })),
      animate(m.angle, target.angle, spring({ stiffness: 45, damping: 16, mass: 1.4 })),
    ]
    if (state === "answer") {
      // one-shot outward bloom: surge past the resting glow, then decay
      // into it — keyframes from the CURRENT value, so re-entry mid-flight
      // stays continuous
      controls.push(
        animate(
          m.outerGlow,
          [null as unknown as number, Math.min(1, target.outerGlow + 0.6), target.outerGlow],
          { duration: 1.6, times: [0, 0.2, 1], ease: ["easeOut", "easeOut"] }
        ),
        animate(
          m.contour,
          [null as unknown as number, Math.min(1, target.contour + 0.25), target.contour],
          { duration: 1.6, times: [0, 0.2, 1], ease: ["easeOut", "easeOut"] }
        )
      )
    } else {
      controls.push(
        animate(m.outerGlow, target.outerGlow, spring({ stiffness: 110, damping: 20 })),
        animate(m.contour, target.contour, spring({ stiffness: 130, damping: 22 }))
      )
    }
    return () => controls.forEach((c) => c.stop())
  }, [state, speedFactor])

  // Feed the springs into the shader once per frame; refresh the palette
  // (theme accent or custom ramp) at a slow cadence.
  const frameCount = React.useRef(0)
  const paletteKey = React.useRef("")
  const colorsRef = React.useRef(colors)
  React.useEffect(() => {
    colorsRef.current = colors
  })
  // Each shader param feeds React state, so an un-quantized read re-renders
  // this instance 60× a second — forever, since springs never land on an
  // exact value. Rounding lets the equality check succeed once a transition
  // settles (zero renders at rest) and sampling every third frame is
  // indistinguishable at these speeds.
  const q = (v: number, p = 100) => Math.round(v * p) / p
  useAnimationFrame(() => {
    const frame = frameCount.current++
    if (frame % 3 === 0) {
      const m = mvRef.current
      setParams((prev) => {
        const next = {
          speed: q(m.speed.get()),
          contour: q(m.contour.get()),
          innerGlow: q(m.innerGlow.get()),
          outerGlow: q(m.outerGlow.get()),
          noise: 0,
          angle: q(m.angle.get(), 10),
        }
        const same =
          next.speed === prev.speed &&
          next.contour === prev.contour &&
          next.innerGlow === prev.innerGlow &&
          next.outerGlow === prev.outerGlow &&
          next.angle === prev.angle
        return same ? prev : next
      })
    }
    if (frame % 30 === 0) {
      const custom = colorsRef.current
      const next =
        custom && custom.length > 0
          ? [resolveHex(custom[0]!) + "00", ...custom.map(resolveHex)]
          : accentRamp()
      const key = next.join()
      if (key !== paletteKey.current) {
        paletteKey.current = key
        setPalette(next)
      }
    }
  })

  return { params, palette }
}

export function OrbCharacter({
  state = "still",
  size = 96,
  speed = 1,
  colors,
  speeds,
  className,
}: OrbCharacterProps) {
  const { params, palette } = useHeatEngine({ state, speed, speeds, colors })
  const hostRef = React.useRef<HTMLDivElement>(null)
  const epoch = useShaderEpoch(hostRef, palette.length > 0)
  const circle = useAmbientAsset(CIRCLE_IMAGE)
  const coreColor =
    colors && colors.length > 0
      ? colors[Math.min(1, colors.length - 1)]!
      : "var(--ambient-accent)"

  return (
    <div
      ref={hostRef}
      aria-hidden
      className={cn("relative overflow-hidden rounded-full", className)}
      style={{
        width: size,
        height: size,
        // frosted glass: the page blurs through; tint and hairline derive
        // from theme tokens
        backdropFilter: "blur(var(--ambient-blur)) saturate(1.15)",
        WebkitBackdropFilter: "blur(var(--ambient-blur)) saturate(1.15)",
        backgroundColor: "var(--glass-core)",
        boxShadow: "inset 0 0 0 1px var(--glass-border)",
      }}
    >
      {/* the accent core — the middle wears the theme; the shell around it
          stays frosted glass, the rim heat renders above */}
      <div
        style={{
          position: "absolute",
          inset: "20%",
          borderRadius: "9999px",
          background: `radial-gradient(circle at 35% 30%, color-mix(in oklab, ${coreColor} 55%, white), ${coreColor} 58%, color-mix(in oklab, ${coreColor} 62%, black))`,
          filter: "blur(2px)",
        }}
      />
      {palette.length > 0 && (
        <Heatmap
          key={epoch}
          width={size}
          height={size}
          image={circle}
          colors={palette}
          colorBack="#00000000"
          contour={params.contour}
          angle={params.angle}
          noise={0}
          innerGlow={params.innerGlow}
          outerGlow={params.outerGlow}
          speed={params.speed}
          scale={1}
          fit="contain"
        />
      )}
    </div>
  )
}

/**
 * OrbHeat — the character's heat, unwrapped: the exact shader the orb
 * renders (same engine, same springs, same circle image, same palette),
 * with none of the character's glass shell. FOR SANCTIONED IDENTITY
 * SURFACES ONLY — the shader-surface rule applies to this export exactly
 * as it does to the character; a product surface wanting it is a
 * governance event. Width/height size the render; `image` picks the heat
 * shape (the character's circle by default, or a surface rect so the heat
 * hugs a band); the box shows whatever slice the host clips.
 */
export function OrbHeat({
  state = "still",
  speed = 1,
  colors,
  speeds,
  width,
  height,
  image,
  scale = 1,
  className,
}: OrbCharacterProps & {
  width: number
  height: number
  /** Asset FILE NAME (not a path) — resolved against the host's assetBase. */
  image?: string
  /** Shape scale within the frame — >1 pushes the rim toward the edges. */
  scale?: number
}) {
  const { params, palette } = useHeatEngine({ state, speed, speeds, colors })
  const hostRef = React.useRef<HTMLDivElement>(null)
  const epoch = useShaderEpoch(hostRef, palette.length > 0)
  const src = useAmbientAsset(image ?? CIRCLE_IMAGE)
  if (palette.length === 0) return null
  return (
    <div ref={hostRef} aria-hidden className={className}>
      <Heatmap
        key={epoch}
        width={width}
        height={height}
        image={src}
        colors={palette}
        colorBack="#00000000"
        contour={params.contour}
        angle={params.angle}
        noise={0}
        innerGlow={params.innerGlow}
        outerGlow={params.outerGlow}
        speed={params.speed}
        scale={scale}
        fit="contain"
      />
    </div>
  )
}

/** The field's shapes — near-full-bleed rounded rects in three aspect
    buckets, so the heat hugs every edge of wide, square, and tall
    surfaces (the loader rejects data URIs, so aspects are bucketed). */
function rectImageFor(w: number, h: number) {
  const ratio = w / h
  if (ratio > 1.4) return "orb-rect-wide.svg?v=3"
  if (ratio < 0.72) return "orb-rect-tall.svg?v=3"
  return "orb-rect.svg?v=4"
}

/**
 * OrbField — the orb's heat as a SURFACE BACKGROUND: the same engine and
 * states, wrapped around a rounded rect that fills the surface behind its
 * glass. One field per open AI surface (only one is ever open), mounted
 * a beat after the entrance so the shader compile can't jank it, fading
 * in on the surface role.
 */
export function OrbField({
  state = "still",
  speed = 1,
  colors,
  speeds,
  strength = "ambient",
  className,
}: OrbCharacterProps & {
  /**
   * "ambient" — a low-presence layer behind surface content (the default).
   * "stage" — the field IS the ground (the canvas page, projectors): full
   * presence, paired with the lighter .ambient-stage-frost.
   */
  strength?: "ambient" | "stage"
}) {
  const { params, palette } = useHeatEngine({ state, speed, speeds, colors })
  const hostRef = React.useRef<HTMLDivElement>(null)
  const epoch = useShaderEpoch(hostRef, palette.length > 0)
  const assetBase = useAmbientRuntime().assetBase
  const [box, setBox] = React.useState<{
    w: number
    h: number
    scale: number
  } | null>(null)
  const [ready, setReady] = React.useState(false)

  React.useEffect(() => {
    const t = window.setTimeout(() => setReady(true), 400)
    return () => window.clearTimeout(t)
  }, [])

  React.useEffect(() => {
    const el = hostRef.current
    if (!el) return
    const ro = new ResizeObserver(([entry]) => {
      const r = entry!.contentRect
      if (r.width <= 0 || r.height <= 0) return
      // RENDER RESOLUTION IS NOT LAYOUT SIZE. The field is a blurred
      // gradient stretched behind frosted glass, so its pixels carry no
      // detail — but at layout size on a retina display a full-page field
      // is millions of fragments per frame, which is what a shader costs.
      // Cap the long edge and let CSS scale it up; the result is identical
      // and the fragment load drops by an order of magnitude.
      const MAX = 360
      const shrink = Math.min(1, MAX / Math.max(r.width, r.height))
      setBox({
        w: Math.max(1, Math.round(r.width * shrink)),
        h: Math.max(1, Math.round(r.height * shrink)),
        scale: 1 / shrink,
      })
    })
    ro.observe(el)
    return () => ro.disconnect()
  }, [])

  return (
    <div
      ref={hostRef}
      aria-hidden
      className={cn(
        // Surfaces oversize the field so the shape's contour (and corners)
        // sit OUTSIDE the clip — only the glow bleeds in. A STAGE field is
        // the ground itself: keep the body in frame and amplify it so the
        // heat carries across a room.
        "pointer-events-none absolute transition-opacity duration-(--motion-surface) ease-(--motion-ease)",
        strength === "stage"
          // saturate only — brightness/contrast wash the ramp toward white,
          // which is exactly the color draining out of the ground
          ? "-inset-[4%] saturate-[1.5]"
          : "-inset-[14%]",
        // ambient light, not a flood — the field stays a low-presence layer
        // and the veil above does the rest
        ready && box && palette.length > 0
          ? strength === "stage"
            ? "opacity-100"
            : "opacity-35"
          : "opacity-0",
        className
      )}
    >
      {ready && box && palette.length > 0 && (
        <div
          className="absolute top-1/2 left-1/2"
          style={{
            width: box.w,
            height: box.h,
            // transform scales the PIXELS, not the layout — the shader keeps
            // sizing itself from this capped box while the visual covers the
            // whole surface (and overshoots it, so a surface that grows never
            // reveals an edge).
            transform: `translate(-50%, -50%) scale(${box.scale * 1.06})`,
            transformOrigin: "center",
          }}
        >
        <Heatmap
          key={epoch}
          width={box.w}
          height={box.h}
          image={`${assetBase.replace(/\/$/, "")}/${rectImageFor(box.w, box.h)}`}
          colors={palette}
          colorBack="#00000000"
          contour={params.contour}
          angle={params.angle}
          noise={0}
          innerGlow={params.innerGlow}
          outerGlow={params.outerGlow}
          speed={params.speed}
          scale={1}
          fit="cover"
        />
        </div>
      )}
    </div>
  )
}

export type { OrbState }
